def max_sub_array(nums):
    n = len(nums)
    best = nums[0]
    for i in range(n):
        s = 0
        for j in range(i, n):
            s += nums[j]
            if s > best:
                best = s
    return best


def main():
    nums = list(map(int, input().split()))
    print(max_sub_array(nums))


if __name__ == "__main__":
    main()

def max_sub_array(nums):
    best = cur = nums[0]
    for x in nums[1:]:
        cur = x if cur < 0 else cur + x
        if cur > best:
            best = cur
    return best


def main():
    nums = list(map(int, input().split()))
    print(max_sub_array(nums))


if __name__ == "__main__":
    main()

def cross_max(nums, l, m, r):
    left = -10**9
    s = 0
    for i in range(m, l - 1, -1):
        s += nums[i]
        left = max(left, s)
    right = -10**9
    s = 0
    for i in range(m + 1, r + 1):
        s += nums[i]
        right = max(right, s)
    return left + right


def dc(nums, l, r):
    if l == r:
        return nums[l]
    m = (l + r) // 2
    return max(dc(nums, l, m), dc(nums, m + 1, r), cross_max(nums, l, m, r))


def max_sub_array(nums):
    return dc(nums, 0, len(nums) - 1)


def main():
    nums = list(map(int, input().split()))
    print(max_sub_array(nums))


if __name__ == "__main__":
    main()
